WITH latest AS (
  SELECT * FROM frontier_commerce.treasury_recon
  WHERE currency LIKE '%${currency}'
    AND ts = (SELECT max(ts) FROM frontier_commerce.treasury_recon WHERE currency LIKE '%${currency}')
)
SELECT max(ts) AS "time", sum(onchain_mist) / 1e9 AS value FROM latest;

WITH latest AS (
  SELECT * FROM frontier_commerce.treasury_recon
  WHERE currency LIKE '%${currency}'
    AND ts = (SELECT max(ts) FROM frontier_commerce.treasury_recon WHERE currency LIKE '%${currency}')
)
SELECT max(ts) AS "time", sum(expected_mist) / 1e9 AS value FROM latest;

WITH latest AS (
  SELECT * FROM frontier_commerce.treasury_recon
  WHERE currency LIKE '%${currency}'
    AND ts = (SELECT max(ts) FROM frontier_commerce.treasury_recon WHERE currency LIKE '%${currency}')
)
SELECT max(ts) AS "time", sum(delta) / 1e9 AS value FROM latest;

WITH latest AS (
  SELECT * FROM frontier_commerce.treasury_recon
  WHERE currency LIKE '%${currency}'
    AND ts = (SELECT max(ts) FROM frontier_commerce.treasury_recon WHERE currency LIKE '%${currency}')
)
SELECT max(ts) AS "time", sum(fees_accrued_mist) / 1e9 AS value FROM latest;

SELECT ts AS time, sum(onchain_mist) / 1e9 AS "on-chain", sum(expected_mist) / 1e9 AS "expected (events)"
FROM frontier_commerce.treasury_recon WHERE currency LIKE '%${currency}' AND $__timeFilter(ts)
GROUP BY ts ORDER BY ts;

SELECT last_success_at, last_poll_at, consecutive_errors, last_fetched, last_inserted,
       total_events, last_error_at, last_error
FROM frontier_commerce.poller_status WHERE id = 1;
